package expo.modules.eventcliprender.realmedia
import org.junit.Test
import org.junit.Assert.*
import java.io.File
import java.nio.file.Files
import java.util.UUID

class ProductExportStoreTest {
 private val project=UUID.randomUUID().toString();private val hash="a".repeat(64)
 private val tracks=listOf(ProductTrackSummary("video/avc",120,0,3966667,33334,4000000,true,0,720,1280),ProductTrackSummary("audio/mp4a-latm",188,0,3989333,21334,4000000,true,0,sampleRate=48000,channels=2))
 private fun root()=Files.createTempDirectory("eventclip-export-test").toFile()
 private fun rejects(block:()->Unit){try{block();fail("Expected guarded failure")}catch(_:IllegalArgumentException){}}
 private class Death:Error()
 @Test fun interruptedPartialCleanedPriorExportAndUnrelatedFilesSurvive(){val r=root();try{val s=ProductExportStore(r);val first=s.begin(project,hash,4000000);s.partial(first).writeText("synthetic-not-mp4");s.publish(first,tracks,33334){false};val bytes=s.retained(first).readBytes();val unknown=File(r,"unrelated.mp4").apply{writeText("do not delete")};val next=s.begin(project,hash,4000000);s.partial(next).writeText("incomplete");ProductExportStore(r).recover();assertFalse(s.partial(next).exists());assertArrayEquals(bytes,s.retained(first).readBytes());assertTrue(unknown.exists());assertEquals(first,s.latest()!!.getProperty("id"));assertEquals("EXPORT_INTERRUPTED",s.status()!!.getProperty("state"))}finally{r.deleteRecursively()}}
 @Test fun processDeathEveryCommitCheckpointNeverDeletesRetainedMovie(){for(stop in listOf("AFTER_BEGIN","AFTER_VALIDATE","AFTER_RETAIN","AFTER_RECORD","AFTER_LATEST")){val r=root();try{val s=ProductExportStore(r){if(it==stop)throw Death()};try{val id=s.begin(project,hash,4000000);s.partial(id).writeText("synthetic-not-mp4");s.publish(id,tracks,33334){false}}catch(_:Death){};val recovery=ProductExportStore(r);recovery.recover();val p=recovery.status()!!;if(stop in listOf("AFTER_BEGIN","AFTER_VALIDATE")){assertEquals("EXPORT_INTERRUPTED",p.getProperty("state"));assertNull(recovery.latest())}else{assertEquals("EXPORT_READY",p.getProperty("state"));assertEquals("false",recovery.latest()!!.getProperty("decodeVerified"));assertTrue(recovery.verifiedFile(p.getProperty("id")).isFile)}}finally{r.deleteRecursively()}}}
 @Test fun cancellationBeforeCommitRemovesPartialOnly(){val r=root();try{val s=ProductExportStore(r);val id=s.begin(project,hash,4000000);s.partial(id).writeText("partial");try{s.publish(id,tracks,33334){true};fail()}catch(_:ExportStopped){};s.stop(id,"EXPORT_CANCELLED");assertFalse(s.partial(id).exists());assertFalse(s.retained(id).exists())}finally{r.deleteRecursively()}}
 @Test fun tamperedRetainedHashFailsClosed(){val r=root();try{val s=ProductExportStore(r);val id=s.begin(project,hash,4000000);s.partial(id).writeText("synthetic-not-mp4");s.publish(id,tracks,33334){false};s.retained(id).writeText("different");rejects{s.verifiedFile(id)}}finally{r.deleteRecursively()}}
 @Test fun auditRejectsTruncationGapsWrongTracksAndDimensionsNotDecodeProof(){ProductExportPolicy.validate(4000000,tracks,33334);for(bad in listOf(tracks.take(1),tracks.map{if(it.mime.startsWith("video"))it.copy(height=720)else it},tracks.map{it.copy(lastPtsUs=2000000)},tracks.map{it.copy(maxGapUs=1000000)},tracks.map{it.copy(duplicates=1)}))rejects{ProductExportPolicy.validate(4000000,bad,33334)}}
 @Test fun workspaceRecoveryOnlyRegisteredFilesAndNoSymlinkTraversal(){val r=root();try{val s=ProductWorkspaces(r);val dir=s.allocate();File(dir,"original.wav").writeText("private temp");val unrelated=File(r,"unknown").apply{mkdir()};File(unrelated,"original.wav").writeText("keep");s.recover();assertFalse(dir.exists());assertTrue(File(unrelated,"original.wav").exists());val next=s.allocate();val keep=File(next,"unrelated").apply{writeText("keep")};try{s.recover();fail()}catch(_:IllegalStateException){};assertTrue(keep.exists());val outside=Files.createTempDirectory("outside").toFile();try{val wav=File(next,"original.wav");Files.createSymbolicLink(wav.toPath(),File(outside,"original.wav").apply{writeText("keep")}.toPath());rejects{s.recover()};assertTrue(File(outside,"original.wav").exists());wav.delete()}finally{outside.deleteRecursively()}}finally{r.deleteRecursively()}}
 @Test fun watermarkMetricsGeometryPortraitLandscapeRotationAndLetterbox(){val l=ProductWatermarkGeometry.box(1280,720,164,18);assertEquals(1076,l.x);assertEquals(668,l.y);assertEquals(18,l.fontPx);val p=ProductWatermarkGeometry.box(720,1280,164,18);assertEquals(516,p.x);assertEquals(1228,p.y);assertEquals(720 to 1280,ProductWatermarkGeometry.displayed(1280,720,90));val fit=ProductWatermarkGeometry.fitted(1280,720,0,720,1280);assertEquals(720.0,fit.first,0.0);assertEquals(405.0,fit.second,0.0);assertTrue(p.y> (1280+fit.second)/2);assertEquals(24,ProductWatermarkGeometry.box(720,1280,150,21).inset);assertEquals(194,ProductWatermarkGeometry.box(720,1280,178,21).width)}
 @Test fun exactPlanFingerprintAndHeadroomAreBounded(){val p=BirthdayProject(project,emptyList());assertEquals(ProductExportPolicy.fingerprint(p),ProductExportPolicy.fingerprint(p.copy()));assertNotEquals(ProductExportPolicy.fingerprint(p),ProductExportPolicy.fingerprint(p.copy(keepDateOrder=false)));assertTrue(ProductExportPolicy.neededBytes(90000000)>180000000);rejects{ProductExportPolicy.neededBytes(90000001)};rejects{ProductExportPolicy.neededBytes(0)}}
}
